        .mission{display:grid;grid-template-columns:280px 1fr;margin:28px 0 80px;border:1px solid #29495a;background:#0b2030;box-shadow:0 25px 70px rgba(0,0,0,.28)}.mission-side{padding:28px;border-right:1px solid #29495a;background:linear-gradient(145deg,#102c3d,#0a1c2a)}.stamp{font-family:"Courier New",monospace;color:var(--orange);font-size:.67rem;letter-spacing:.12em;text-transform:uppercase}.mission-side h2{font-size:2.15rem;line-height:.94;margin:14px 0 12px}.mission-side p{color:var(--muted);line-height:1.45;font-size:.94rem}.meters{display:grid;gap:15px;margin-top:28px}.meter-label{display:flex;justify-content:space-between;font-family:"Courier New",monospace;font-size:.67rem;text-transform:uppercase;letter-spacing:.07em}.track{height:5px;background:#18394b;margin-top:7px;overflow:hidden}.fill{height:100%;width:0;background:var(--gold);transition:width .65s cubic-bezier(.2,.8,.2,1)}#trustFill{background:var(--cyan)}.mission-main{padding:clamp(24px,5vw,48px)}.progress{display:flex;gap:8px;margin-bottom:26px}.progress i{height:5px;flex:1;background:#18384a;transition:.35s}.progress i.done{background:var(--gold);box-shadow:0 0 12px rgba(255,195,77,.4)}
        .scenario{min-height:118px}.scenario small{font-family:"Courier New",monospace;color:var(--cyan);text-transform:uppercase;letter-spacing:.1em}.scenario h3{font-size:clamp(1.7rem,4vw,3rem);line-height:1.05;margin:10px 0 8px}.scenario p{color:#bfd0cd;font-size:1.02rem;line-height:1.5;max-width:700px}.routes{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:24px}.route{position:relative;text-align:left;padding:18px 16px 16px;border:1px solid #365567;background:#102b3d;color:var(--cream);cursor:pointer;min-height:124px;transition:transform .18s,border-color .18s,background .18s}.route:hover,.route:focus-visible{transform:translateY(-3px);border-color:var(--gold);background:#14364a;outline:none}.route:disabled{opacity:.55;cursor:default;transform:none}.route-icon{font-size:1.35rem;color:var(--gold);display:block;margin-bottom:10px}.route strong{display:block;font-size:1.05rem}.route span{display:block;color:#9fbbb9;font-size:.78rem;line-height:1.35;margin-top:5px;font-family:"Courier New",monospace}.debrief{display:none;margin-top:19px;padding:14px 16px;border-left:3px solid var(--gold);background:#142f40;line-height:1.45;color:#d6ded5}.debrief.show{display:block;animation:rise .35s ease}.next{display:none;margin-top:16px;border:0;background:var(--gold);color:#132534;padding:12px 20px;font-weight:bold;cursor:pointer;box-shadow:5px 5px 0 var(--orange)}.next.show{display:inline-block}.next:active{transform:translate(3px,3px);box-shadow:2px 2px 0 var(--orange)}
