<main class="wrap">
    <header>
        <div><div class="eyebrow">A small-pieces rescue operation</div><h1>Walled<br><span class="open">Garden</span><br>Rescue</h1><p class="intro">Six useful little contributions are trapped behind a platform wall. Choose where each one should live before the garden goes dark.</p></div>
        <aside class="manifesto"><strong>“The blog is the social network.”</strong>Jon argued that open, loosely joined places outlive fashionable platforms. This is the argument, disguised as a tiny night mission.</aside>
    </header>

    <figure class="board" aria-label="Illustration of ideas escaping a closed garden into an open network of personal sites">
        <img class="board-image" src="walled-garden-rescue.webp" alt="Glowing notes cross a drawbridge from a dark walled garden toward a network of warm personal websites">
        <span class="board-label left">closed / fading</span><span class="board-label right">open / growing</span>
    </figure>

    <section class="mission" aria-live="polite">
        <aside class="mission-side"><span class="stamp">Rescue docket 04-2005</span><h2>Move the pearls of wisdom</h2><p>There is no universally perfect channel. Match durability, public usefulness, and human tenderness to the contribution.</p><div class="meters"><div><div class="meter-label"><span>Open reach</span><b id="reachValue">0</b></div><div class="track"><div class="fill" id="reachFill"></div></div></div><div><div class="meter-label"><span>Human trust</span><b id="trustValue">0</b></div><div class="track"><div class="fill" id="trustFill"></div></div></div></div></aside>
        <div class="mission-main">
            <div class="progress" id="progress" aria-label="Mission progress"></div>
            <div id="round">
                <div class="scenario"><small id="counter"></small><h3 id="title"></h3><p id="copy"></p></div>
                <div class="routes">
                    <button class="route" data-route="blog"><span class="route-icon">✦</span><strong>Own the address</strong><span>Publish on your blog · linkable · lasting</span></button>
                    <button class="route" data-route="thread"><span class="route-icon">⌁</span><strong>Join the open thread</strong><span>Public reply · conversational · connected</span></button>
                    <button class="route" data-route="private"><span class="route-icon">✉</span><strong>Send it privately</strong><span>Direct note · intimate · deliberately limited</span></button>
                </div>
                <div class="debrief" id="debrief"></div><button class="next" id="next">Open the next gate →</button>
            </div>
            <div class="finish" id="finish"><div class="seal">⌂</div><h3>The ideas are free.</h3><p id="verdict"></p><button class="next show" id="restart">Run another rescue</button></div>
        </div>
    </section>

    <footer class="source"><p><span class="tiny">Field notes, 4 April 2005</span>Inspired by Jon’s <a href="<?= htmlspecialchars($sourceUrl) ?>" target="_blank" rel="noopener">The Blog Is The Social Network</a>.</p><a href="index.php">See every experiment →</a></footer>
</main>
<script>
const missions=[
 {t:'A fix nobody should have to rediscover',c:'You finally solve a nasty Linux audio problem. Search results are full of dead ends. Where does the durable explanation belong?',best:'blog',why:{blog:'Yes. A stable, linkable write-up can keep rescuing strangers long after tonight.',thread:'Useful conversation, but the fix may become a buried reply. Give it a canonical home too.',private:'Kind, but only one person benefits. This pearl wants daylight.'}},
 {t:'A friend is carrying something heavy',c:'They mention grief in a public post. Your response is personal, specific, and meant for them rather than an audience.',best:'private',why:{blog:'This turns someone else’s vulnerable moment into your publication. Too much stage, not enough shelter.',thread:'A brief public kindness can help, but the real note deserves privacy.',private:'Exactly. Open does not mean exposed. A direct note protects tenderness and deepens trust.'}},
 {t:'An essay gets one important thing wrong',c:'The author welcomes discussion, and your correction would help everyone reading the original argument.',best:'thread',why:{blog:'A response post can work, especially if the thought needs room, but keep the link between both pieces visible.',thread:'Yes. The correction stays beside the claim and invites the author into the exchange.',private:'Courteous, but the other readers remain misled. Put the useful part where the conversation lives.'}},
 {t:'A tiny tool deserves a front door',c:'You make a one-purpose calculator that saves three annoying minutes every week. It needs a home people can bookmark.',best:'blog',why:{blog:'Perfect. A tiny tool at a durable address is a splendid little piece, loosely joined.',thread:'A thread can announce it, but should not be the only doorway.',private:'Sending it to friends is lovely distribution, not a durable home.'}},
 {t:'A family photograph from an ordinary Tuesday',c:'It matters greatly to four people and not at all to the search index. The child in it did not ask to become content.',best:'private',why:{blog:'Not every meaningful thing must become public. Keep this garden gate gently closed.',thread:'A public feed adds reach but no value here.',private:'Right. Limited circulation can be a feature, not a failure.'}},
 {t:'A brilliant reply on a platform due to close',c:'Your comment explains a useful principle better than anything else you have written. Export day is tomorrow.',best:'blog',why:{blog:'Rescued. Give the idea an address you control, then link back while the old place still breathes.',thread:'Another open thread is better than a dead silo, but a canonical copy makes it portable.',private:'A private archive saves it for you, not for the people it could help.'}}
];
let step=0,reach=0,trust=0,locked=false;
const $=s=>document.querySelector(s), buttons=[...document.querySelectorAll('.route')];
function start(){step=0;reach=0;trust=0;locked=false;$('#finish').classList.remove('show');$('#round').style.display='block';$('#progress').innerHTML=missions.map(()=>'<i></i>').join('');updateMeters();render()}
function render(){locked=false;buttons.forEach(b=>b.disabled=false);$('#debrief').classList.remove('show');$('#next').classList.remove('show');let m=missions[step];$('#counter').textContent=`Pearl ${step+1} of ${missions.length}`;$('#title').textContent=m.t;$('#copy').textContent=m.c}
function updateMeters(){reach=Math.min(100,reach);trust=Math.min(100,trust);$('#reachValue').textContent=reach;$('#trustValue').textContent=trust;$('#reachFill').style.width=reach+'%';$('#trustFill').style.width=trust+'%'}
buttons.forEach(b=>b.addEventListener('click',()=>{if(locked)return;locked=true;buttons.forEach(x=>x.disabled=true);const route=b.dataset.route,m=missions[step],ideal=route===m.best;if(route==='blog')reach+=20;if(route==='thread'){reach+=13;trust+=8}if(route==='private')trust+=20;if(ideal){reach+=4;trust+=4}updateMeters();document.querySelectorAll('#progress i')[step].classList.add('done');$('#debrief').innerHTML=`<strong>${ideal?'Good instinct.':'A defensible choice, with a trade-off.'}</strong> ${m.why[route]}`;$('#debrief').classList.add('show');$('#next').classList.add('show')}));
$('#next').addEventListener('click',()=>{step++;if(step<missions.length)render();else finish()});
function finish(){$('#round').style.display='none';$('#finish').classList.add('show');let voice=reach>=trust?'You built a bright public commons without forgetting that people sometimes need a quiet room.':'You protected the human bonds at the centre of the network, while leaving useful lanterns for strangers to find.';$('#verdict').textContent=voice+' The healthiest web has front porches, pathways, and a few curtains.'}
$('#restart').addEventListener('click',start);start();
</script>
